def IM(name, h=190): return FIG(name).replace('<img class="fig"', f'<img style="height: {h}px; border-radius: 12px; border: 3px solid #D5DEEA; vertical-align: middle"')
def SV(svg, h=200): return svg.replace('<svg class="svgfig', f'<svg style="height: {h}px; width: auto; vertical-align: middle" class="svgfig')
def K(t): return f'<b style="color: #C2410C">{t}</b>'
def MX(w, n, d): return f'<span style="display: inline-flex; align-items: center; gap: .12em; direction: rtl; unicode-bidi: isolate">{w}{FR(n, d)}</span>'   # العدد الكامل يمين الكسر
def RM(r): return f'<span style="font-size: .7em; color: #3B5480">والباقي {r}</span>'
def BARS(den, num, h=64):   # num جزءاً من أجزاءٍ حجمها 1/den: مستطيلاتٌ كاملة من اليمين ثم الجزء الباقي
    k = -(-num // den)
    return ('<span style="display: inline-flex; gap: 14px; direction: rtl; vertical-align: middle">'
            + ''.join(SV(FBAR(den, min(den, num - i * den), color='#16A34A' if num - i * den >= den else '#F59E0B', label=False, w=180), h) for i in range(k)) + '</span>')
